import { strToU8, zipSync } from 'fflate'
import { buildDocx } from './docxBuilder'
import { buildPptx, escapeXml, textBox } from './pptxBuilder'

/**
 * A corpus of Arabic Office documents, generated by code so it can be regenerated at will (tests/unit/officeRtl*.test.ts
 * use it; `EPDF_WRITE_CORPUS=1 npx vitest run tests/unit/officeRtlCorpus.test.ts` writes the files, Epdf's PDFs and,
 * when LibreOffice is installed, LibreOffice's reference PDFs to test-results/office-rtl/).
 *
 * Every document lists the logical source strings of its paragraphs (`paras`) with the side their first line must be
 * aligned to (`side`, physical: what a reader sees), and whether the paragraph is short enough to fit on one line.
 */

export interface ExpectedPara {
  /** Logical text as typed (list markers included as they are read: marker, space, text). */
  text: string
  /** Physical side the paragraph's lines are aligned to (for justified paragraphs: the side of the last line). */
  side?: 'left' | 'right' | 'center'
  /** Fits on one line: the page text model must return exactly this line. */
  oneLine?: boolean
  /** Where the text is (body, header, footer, table). */
  where?: 'body' | 'header' | 'footer' | 'table' | 'cell' | 'tab'
}

export interface CorpusDoc {
  name: string
  bytes: Uint8Array
  paras: ExpectedPara[]
  /** Table/sheet header texts in LOGICAL column order (the first must be the rightmost in a right-to-left table). */
  columns?: string[]
}

